export const isVerifiedWatch=p=>p?.type==='watch'&&p.watchProfile?.reviewed===true;
const smooth=x=>{const t=Math.max(0,Math.min(1,x));return t*t*t*(t*(t*6-15)+10);};
// One deliberate lift, hold and return. Position, velocity and acceleration meet at each boundary.
export function watchGesture(time,reduced=false){
 if(reduced||!Number.isFinite(time)||time<0)return 0;
 const t=Math.min(4.5,time);return t<1.1?smooth(t/1.1):t<3?1:1-smooth((t-3)/1.5);
}
export function watchPose(time,reduced=false,rest=null){
 const reach=reduced?1:watchGesture(time),targets=[{x:-1.5,y:33,z:11},{x:.5,y:36,z:10}];
 return {reach,hands:targets.map((b,i)=>{const a=rest?.[i]||{x:(i?1:-1)*7.8,y:23.8,z:2};return {x:a.x+(b.x-a.x)*reach,y:a.y+(b.y-a.y)*reach,z:a.z+(b.z-a.z)*reach};})};
}
export function watchFactsHTML(p,esc){
 if(!isVerifiedWatch(p))return '';
 return `<div class="apparel-facts watch-facts"><p><strong>Case diameter:</strong> ${p.watchProfile.caseMM} mm · ${esc(p.watchProfile.movement)} · ${p.watchProfile.date===false?'no date display':'date display'}.</p><p>${esc(p.sizeBasis)}</p><p>${esc(p.sourceOfferNote)}</p>${p.watchProfile.diveReference?`<details class="watch-photo-notes"><summary>Body, bracelet & photograph</summary><p>Reference ${esc(p.referenceSKU)} · ${p.watchProfile.thicknessMM} mm case thickness · ${p.watchProfile.lugMM} mm lug width. These are manufacturer dimensions; the photograph does not measure wrist fit.</p><p>${esc(p.watchProfile.photoNote)}</p><p>Photograph by ${esc(p.watchProfile.photoAuthor)} · <a href="${esc(p.watchProfile.photoLicenseUrl)}" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0</a>. Converted to WebP without cropping or resizing. Original simplified 3D geometry has no copied brand marks or photograph texture.</p><a href="${esc(p.watchProfile.manufacturerSource)}" target="_blank" rel="noopener noreferrer">Manufacturer specifications ↗</a></details>`:''}</div>`;
}

export function watchStudyHTML(s,st,step,esc){const p=st.products.find(p=>p.watchProfile?.diveReference);if(!p)return '';step=Number.isSafeInteger(step)?((step%12)+12)%12:0;return `<div class="modal-body watch-study"><span class="eyebrow">CASE & BEZEL STUDY · FREE TO READ</span><h3>A small case, a clear reference.</h3><p>${esc(p.name)} · 37 mm case diameter, 11.2 mm thickness and 20 mm lug width. These measurements describe the watch, not your wrist.</p><div class="watch-study-layout"><div><svg class="watch-study-drawing" viewBox="0 0 220 270" role="img" aria-label="Original no-date watch diagram with an illustrative rotating bezel" data-static="${s.preferences.reducedMotion}"><rect x="88" y="3" width="44" height="264" rx="9" fill="#aab3b2"/><path d="M100 5V265M120 5V265" stroke="#d6dcda" stroke-width="3"/><circle cx="110" cy="135" r="89" fill="#a8b4b1"/><g class="study-bezel" style="transform:rotate(${-step*30}deg);transform-origin:110px 135px"><circle cx="110" cy="135" r="82" fill="#252d2a"/><path d="M110 59L105 68H115Z" fill="#e9dfbd"/>${[10,20,30,40,50].map((v,i)=>{const a=(i+1)*Math.PI/3;return `<text x="${110+Math.sin(a)*72}" y="${139-Math.cos(a)*72}" text-anchor="middle" fill="#e9dfbd" font-size="12">${v}</text>`;}).join('')}</g><circle cx="110" cy="135" r="60" fill="#171d1b"/>${Array.from({length:12},(_,i)=>{const a=i*Math.PI/6;return `<circle cx="${110+Math.sin(a)*49}" cy="${135-Math.cos(a)*49}" r="${i%3?3:4}" fill="#ddd4ad"/>`;}).join('')}<path d="M110 135L87 122M110 135L139 118" stroke="#ddd4ad" stroke-width="5" stroke-linecap="round"/></svg><div class="watch-study-controls"><button class="button secondary" data-action="watch-bezel">Turn diagram 5 minutes ↺</button><button class="button secondary" data-action="watch-zero">Reset diagram</button></div><p role="status" class="watch-study-status">Illustrative alignment: ${step*5} minutes. This diagram is not a timer.</p></div><div><h4>Read the exact selected format</h4><p>A black, no-date dial and a steel three-link bracelet. The manufacturer describes a one-way aluminum-insert bezel without individual minute hash marks.</p><p>Self-winding MT5400 movement. Approximate manufacturer power reserve: 70 hours. Published water-resistance rating: 200 m; no water performance is simulated.</p><p>Bracelet length and a wrist-size range are not established. Virtual fitting is a styling preview.</p><p>Reading and turning this diagram spend no game money, time, stamina or XP. They reserve no stock.</p><a href="${esc(p.watchProfile.manufacturerSource)}" target="_blank" rel="noopener noreferrer">Manufacturer reference ↗</a></div></div><button class="button secondary wide" data-action="collection-open">Back to the collection desk</button></div>`;}
